-- Previous question ids (e.g. EQUIP-K-01) share (section_id, number) with the new ones: park them first.
update public.competency_questions set number = number + 10000 where id !~ '::';
insert into public.competency_questions (id, competency_id, section_id, number, text, sort_order, needs_source_review) values
('patient-assessment-reassessment-and-vital-signs::knowledge_1','patient-assessment-reassessment-and-vital-signs','patient-assessment-reassessment-and-vital-signs:knowledge',1,'State the nurse''s role and responsibility in completing a Comprehensive Patient Assessment, Reassessment and Vital Signs for a patient in area of practice and comparing findings with the patient''s baseline findings are so important to overall assessment.',1001,false),
('patient-assessment-reassessment-and-vital-signs::knowledge_2','patient-assessment-reassessment-and-vital-signs','patient-assessment-reassessment-and-vital-signs:knowledge',2,'Verbalize the role and responsibilities of the nurse and the need to start the assessment with taking a full Health History, family history, psychosocial history and activities of daily living.',1002,false),
('patient-assessment-reassessment-and-vital-signs::knowledge_3','patient-assessment-reassessment-and-vital-signs','patient-assessment-reassessment-and-vital-signs:knowledge',3,'Discuss why assessment involves collecting both subjective and objective data of the presenting complaint.',1003,false),
('patient-assessment-reassessment-and-vital-signs::knowledge_4','patient-assessment-reassessment-and-vital-signs','patient-assessment-reassessment-and-vital-signs:knowledge',4,'Explain why observing the patient''s body language during assessment is important.',1004,false),
('patient-assessment-reassessment-and-vital-signs::knowledge_5','patient-assessment-reassessment-and-vital-signs','patient-assessment-reassessment-and-vital-signs:knowledge',5,'State the PQRSTP model of exploring the chief complaint i.e. Proactive or palliative (provokes or relieves symptoms), quality or quantity (what does symptom/s feel, look or sound like), region or radiation (where is the symptom/s) severity of symptom/s including PAIN SCORE, timing (when was it sudden, how often and how long does symptom/s last), psychosocial history, (find out how the patient feels about himself, his place in society and his relationships with others).',1005,false),
('patient-assessment-reassessment-and-vital-signs::knowledge_6','patient-assessment-reassessment-and-vital-signs','patient-assessment-reassessment-and-vital-signs:knowledge',6,'Explain how to properly observe the patient using ''some teams'' – symmetry (are face and body symmetrical!?), old (do they look their age?), mentation (are they alert confused agitated or inattentive?), expression (do they appear ill, in pain or anxious?) trunk (are they thin, stocky, obese or barrel-chested?), extremities (are the fingers clubbed, are there joint abnormalities or edema?), appearance (are they clean and appropriately dressed?), movement (is their posture, gait and coordination normal, are they mobile and able to ambulate normally?), speech (is their speech relaxed, clear, strong, understandable and appropriate, do they sound stressed?).',1006,false),
